use phonebook_rt as rt;
use std::collections::BTreeMap;

/// 000-0000001  TALLY_OF
///
/// A local extension: this is custom logic, not a registered address.
fn tally_of(entry: &(String, i64)) -> i64 {
    let entry: (String, i64) = entry.clone();
    let tally: i64 = entry.1.clone();
    tally
}

/// 000-0000002  AS_LINE
///
/// A local extension: this is custom logic, not a registered address.
fn as_line(entry: &(String, i64)) -> String {
    let entry: (String, i64) = entry.clone();
    let word: String = entry.0.clone();
    let tally: i64 = entry.1.clone();
    let shown: String = rt::core::to_text(&tally);
    let parts: Vec<String> = vec![word.clone(), shown.clone()];
    let line: String = parts.join(": ".to_string().as_str());
    line
}

fn main() {
    let raw: String = rt::io_::read_text_file(&"examples/data/speech.txt".to_string());
    let lowered: String = raw.to_ascii_lowercase();
    let nodots: String = rt::text::replace(&lowered, &".".to_string(), &" ".to_string());
    let clean: String = rt::text::replace(&nodots, &",".to_string(), &" ".to_string());
    let words: Vec<String> = rt::text::split_words(&clean);
    let tallies: BTreeMap<String, i64> = rt::collections_::count_occurrences(&words);
    let entries: Vec<(String, i64)> = rt::collections_::entries(&tallies);
    let ranked: Vec<(String, i64)> = rt::collections_::sort_by(&entries, tally_of, &true);
    let top: Vec<(String, i64)> = rt::collections_::take(&ranked, &10);
    let report: Vec<String> = top.iter().map(|_pb_x| as_line(_pb_x)).collect::<Vec<_>>();
    rt::core::print_lines(&report);
}
